    for (i = 0; i < 2; i++) {
        av_freep(&s->ref_index[i]);
        av_freep(&s->motion_val_base[i]);
        s->cur_pic.ref_index[i]  = NULL;
        s->cur_pic.motion_val[i] = NULL;
    }
